function main(ctx) {
  if (ctx.phase == 'enable') { return null }
  if (ctx.command != 'hello') { return null }
  var count = integer(ctx.state['count'])
  if (count == null) { count = 0 }
  ctx.state['count'] = count + 1
  return {
    format: 'markdown',
    content: '### ' + markdown_escape(ctx.config['greeting']) + '\n\n' + markdown_escape(clean_name(ctx.message['sender_name'])) + '，这是本会话第 ' + str(count + 1) + ' 次问候。\n\n' + markdown_escape(ctx.args.join(' ')),
    buttons: [[{label: '再次问候', data: '/hello'}]]
  }
}
